/* ATB Atlas V13 — Spectral Instrument. Focused workbench, context on demand. */
'use strict';
const app=document.getElementById('app');
const icon=(name,n=18)=>`<img src="./assets/icons/${name}.svg" width="${n}" height="${n}" class="icon" alt="" aria-hidden="true">`;
const escapeHtml=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');
const store={get(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const themes={
  pigment:['#C24E78','#DC7544','#8E5CBD','#43885B','#D09E39','#3284BD','#B36A3C','#148F91','#947D45','#7A6BB5','#D35C9A','#78A545'],
  citrus:['#DD526F','#F2923C','#8151D4','#209E77','#D1A11D','#3675D7','#CE693A','#119EAE','#A89B2F','#9759B9','#ED6E9B','#819B3D'],
  garden:['#9F486E','#D57B4B','#7F59AC','#4D9762','#C89D4B','#4775AC','#B26D42','#279A8B','#9E9B45','#6E68BC','#C45B8F','#6F995C'],
  night:['#FC7FA3','#FFA166','#B99AFE','#83C999','#F0C969','#83BFFF','#EAA183','#57CDCA','#BEB45F','#AAACFF','#F797CF','#B4D477']
};
const catLabels={pigment:'Mineral & Ink',citrus:'Chromatic Signal',garden:'Botanical',night:'After Hours'};
const initial=store.get('atb_v12_colors');
const selectedTheme=store.get('atb_v12_theme');
const state={route:'mapa',lens:'bands',group:'all',pathogen:'all',family:'all',drug:'all',status:'all',onlyKnown:true,query:'',page:0,pageSize:9,toolsOpen:false,theme:selectedTheme&&themes[selectedTheme]?selectedTheme:'pigment',colors:initial||null,active:{type:'guide'},focus:'none',compare:['cefepima','ceftriaxona','meropenem'],study:'s-aureus-mrsa',course:0,lesson:0,syndrome:'nac',quizAnswer:null,quizStep:0,prefs:store.get('atb_v12_prefs')||{compact:false,motion:true},modal:null,globalQuery:'',saved:store.get('atb_v12_saved')||[],favorites:store.get('atb_v12_faves')||[],clinicalTab:'signals',navOpen:false};
const statuses={active:{mark:'✓',label:'Actividad habitual',short:'Habitual',text:'Actividad descrita en esta relación. La susceptibilidad real y el contexto deben confirmarse.'},conditional:{mark:'≈',label:'Actividad variable',short:'Variable',text:'Depende de especie, fenotipo, pruebas de susceptibilidad, sitio y otros factores.'},none:{mark:'×',label:'Sin actividad útil',short:'No útil',text:'Esta relación del corpus describe ausencia de actividad clínicamente útil.'},unknown:{mark:'·',label:'No evaluado',short:'Sin datos',text:'Este cruce no está evaluado en el atlas. No significa resistencia ni inactividad.'}};
const routes=[['mapa','table-2','Mapa de espectro'],['microorganismos','microscope','Microorganismos'],['antibioticos','pill','Antibióticos'],['clinica','stethoscope','Síndromes clínicos'],['comparar','columns-3','Comparador'],['laboratorio','flask-conical','Laboratorio'],['aprender','graduation-cap','Aprender'],['fuentes','book-open','Fuentes']];
const coreGroups=['staph','strep','entero','enterobacterales','nonfermenters','anaerobes','atypicals','mycobacteria'];
let D=null,X=null,rmap=new Map(),drugRel=new Map(),microRel=new Map();
const G=id=>D.groups.find(x=>x.id===id),A=id=>D.antibiotics.find(x=>x.id===id),P=id=>D.pathogens.find(x=>x.id===id),S=id=>D.syndromes.find(x=>x.id===id);
const rel=(a,p)=>rmap.get(a+'|'+p);
const relatives=(map,id)=>map.get(id)||[];
const color=id=>state.colors?.[id]||themes[state.theme][Math.max(0,D.groups.findIndex(x=>x.id===id))%12];
const tint=id=>`style="--tax:${escapeHtml(color(id))}"`;
const families=()=>[...new Set(D.antibiotics.map(x=>x.family))].sort((a,b)=>a.localeCompare(b,'es'));
const groupMembers=id=>D.pathogens.filter(p=>p.groupId===id);
const status=r=>r?.status&&statuses[r.status]?r.status:'unknown';
const statusChip=(s,full=false)=>`<span class="status-token st-${s}"><b>${statuses[s].mark}</b><span>${escapeHtml(full?statuses[s].label:statuses[s].short)}</span></span>`;
const pill=(t)=>`<span class="small-pill">${escapeHtml(t)}</span>`;
const refs=ids=>(ids||[]).map(key=>{const v=D.guides[key];return v?`<a href="${escapeHtml(v.url||'#')}" target="_blank" rel="noopener noreferrer">${escapeHtml(v.title||key)} ${icon('arrow-up-right',12)}</a>`:''}).filter(Boolean).join('')||'<span class="muted">Referencia individual pendiente</span>';
const short=name=>String(name||'').replace(' (sin fenotipo de resistencia definido)','').replace(' (sin DTR definido)','');
function num(n){return String(n).padStart(2,'0')}
function hrefMode(path){return '#/'+path}
function navigate(page){state.modal=null;state.navOpen=false;history.replaceState(null,'',location.pathname+location.search+hrefMode(page));state.route=page;render();window.scrollTo({top:0,behavior:'instant'});}
function persist(){store.set('atb_v12_colors',state.colors);store.set('atb_v12_theme',state.theme);store.set('atb_v12_prefs',state.prefs);store.set('atb_v12_saved',state.saved);store.set('atb_v12_faves',state.favorites)}
function titleOf(){return routes.find(x=>x[0]===state.route)?.[2]||'ATB Atlas'}
function shell(body){const nav=routes.map(([id,ico,label],i)=>`<button data-act="go:${id}" class="instrument-tab ${state.route===id?'selected':''}"><span class="tab-icon">${icon(ico,17)}</span><span>${escapeHtml(label)}</span></button>`).join('');return `<div class="instrument-shell ${state.prefs.motion?'motion-on':'motion-off'} ${state.prefs.compact?'is-compact':''}">
<header class="instrument-mast"><button data-act="go:mapa" class="instrument-brand" aria-label="ATB Atlas inicio"><span class="emblem"><span>ATB</span><i>+</i></span><span class="brand-word"><strong>ATB Atlas</strong><small>MICROBIOLOGY FIELD INSTRUMENT</small></span></button>
<div class="mast-tools"><button class="mast-search" data-act="modal:search">${icon('search',17)} <span>Buscar en todo el atlas</span><kbd>⌘ K</kbd></button><button class="mast-icon" data-act="modal:palette" aria-label="Personalizar colores">${icon('palette',18)}</button><button class="mast-icon" data-act="share" aria-label="Compartir enlace">${icon('share-2',18)}</button><button class="mast-icon mobile-nav" data-act="toggle-nav" aria-label="Abrir navegación">${icon('layers',19)}</button></div></header>
<nav class="instrument-navigation ${state.navOpen?'nav-open':''}" aria-label="Navegación de ATB Atlas">${nav}</nav>
<main id="stage" class="instrument-stage">${body}</main>
<footer class="instrument-footer"><span>ATB / SPECTRUM INSTRUMENT · V13</span><span>Material educativo · Sin evaluar ≠ resistente · Verificar microbiología y guías clínicas</span></footer>
${state.modal?modalMarkup():''}</div>`;}
function eyebrow(text){return `<span class="eyebrow"><i></i>${text}</span>`}
function pageHeading(index,title,desc,aside=''){return `<div class="page-heading"><div>${eyebrow(index)}<h1>${title}</h1><p>${desc}</p></div>${aside?`<div class="page-heading-aside">${aside}</div>`:''}</div>`}
function intentBar(){const items=[['mapa','table-2','Cruzar datos','Microorganismo × antibiótico','cherry'],['microorganismos','microscope','Entender el micro','Morfología, resistencia, síndromes','kiwi'],['antibioticos','pill','Entender el ATB','Familias, mecanismos, límites','marigold']];return `<div class="intent-bar">${items.map(([url,ico,head,sub,shade])=>`<button class="intent intent-${shade} ${state.route===url?'selected':''}" data-act="go:${url}"><span class="intent-icon">${icon(ico,22)}</span><span><b>${head}</b><small>${sub}</small></span>${icon('arrow-up-right',17)}</button>`).join('')}</div>`}
function legend(inline=false){return `<div class="legend-inner">${Object.entries(statuses).map(([key,def])=>`<button data-act="status-help:${key}" class="legend-item"><span class="legend-symbol st-${key}">${def.mark}</span><span><b>${def.short}</b>${!inline?`<small>${key==='unknown'?'No hay información':key==='none'?'Actividad no útil':key==='conditional'?'Según contexto':'Verifica susceptibilidad'}</small>`:''}</span></button>`).join('')}</div>`}
function groupSelector(){const visible=D.groups;return `<div class="territory-headline"><span class="eyebrow">TERRITORIOS MICROBIOLÓGICOS</span><span>Elige un grupo para acercarte al detalle</span></div><div class="territory-strip"><button class="territory-tag ${state.group==='all'?'selected':''}" data-act="group:all"><span class="all-micro-pip">✳</span><b>Todos</b><small>${D.groups.length}</small></button>${visible.map(g=>`<button class="territory-tag ${state.group===g.id?'selected':''}" data-act="group:${g.id}" ${tint(g.id)}><i></i><b>${escapeHtml(g.name)}</b><small>${groupMembers(g.id).length}</small></button>`).join('')}</div>`;}
function mapGroupList(){let gs=state.group==='all'?D.groups.filter(x=>coreGroups.includes(x.id)):D.groups.filter(x=>x.id===state.group);if(state.pathogen!=='all')gs=gs.filter(x=>x.id===P(state.pathogen)?.groupId);return gs}
function mapDrugList(){let list=D.antibiotics.filter(a=>state.family==='all'||a.family===state.family);
 if(state.drug!=='all')list=list.filter(a=>a.id===state.drug);
 if(state.onlyKnown&&state.drug==='all')list=list.filter(a=>relatives(drugRel,a.id).length);
 if(state.status!=='all')list=list.filter(a=>D.pathogens.some(p=>(state.pathogen==='all'||p.id===state.pathogen)&&(state.group==='all'||p.groupId===state.group)&&status(rel(a.id,p.id))===state.status));
 if(state.query){const q=norm(state.query);list=list.filter(a=>norm(a.name+' '+a.family+' '+(a.subgroup||'')).includes(q));}
 return list.sort((a,b)=>a.family.localeCompare(b.family,'es')||a.name.localeCompare(b.name,'es'));
}
function statusSegments(a,g){const members=groupMembers(g.id).filter(p=>state.pathogen==='all'||p.id===state.pathogen);const values=members.map(p=>status(rel(a.id,p.id)));return {members,values,known:values.filter(x=>x!=='unknown').length,active:values.filter(x=>x==='active').length};}
function mapBand(a,g){const s=statusSegments(a,g);return `<button class="signal-lane" ${tint(g.id)} data-act="inspect:${a.id}:${g.id}" aria-label="${escapeHtml(a.name)} frente a ${escapeHtml(g.name)}. ${s.known} de ${s.members.length} cruces registrados"><span class="lane-track">${s.values.map((k,i)=>`<span class="lane-segment st-${k}" title="${escapeHtml(s.members[i].name)} · ${statuses[k].label}"><span>${statuses[k].mark}</span></span>`).join('')||'<span class="lane-empty">—</span>'}</span><span class="lane-count"><b>${s.known}</b><span>/ ${s.members.length} con dato</span><span class="lane-chevron">›</span></span></button>`;}
function mapTable(){const groups=mapGroupList(),all=mapDrugList(),size=state.pageSize,page=Math.min(state.page,Math.max(0,Math.ceil(all.length/size)-1));state.page=page;const drugs=all.slice(page*size,(page+1)*size);let rows='',family='';for(const a of drugs){if(family!==a.family){family=a.family;rows+=`<tr class="atlas-family-row"><th colspan="${groups.length+1}"><span class="fam-marker"></span>${escapeHtml(family)} <span class="fam-tally">${all.filter(x=>x.family===family).length} registrados</span></th></tr>`;}rows+=`<tr class="atlas-drug-row"><th class="atlas-drug-title"><button data-act="drug-open:${a.id}"><b>${escapeHtml(short(a.name))}</b><small>${escapeHtml(a.subgroup||'Ver perfil')}</small></button></th>${groups.map(g=>`<td>${state.lens==='precision'?precisionCells(a,g):mapBand(a,g)}</td>`).join('')}</tr>`;}const total=Math.ceil(all.length/size);return `<div class="spectrum-viewport" tabindex="0" aria-label="Mapa de cobertura con desplazamiento horizontal"><table class="signal-table ${state.lens==='precision'?'precision-mode':''}"><thead><tr><th class="signal-corner"><span>FÁRMACO ↓</span><span>MICROORGANISMO →</span></th>${groups.map(g=>`<th class="signal-heading" ${tint(g.id)}><button data-act="group:${g.id}"><i></i><b>${escapeHtml(g.name)}</b><small>${groupMembers(g.id).length} microorganismos</small></button></th>`).join('')}</tr></thead><tbody>${rows||`<tr><td class="empty-signal" colspan="${groups.length+1}">No hay coincidencias para estos filtros. Prueba limpiar la selección.</td></tr>`}</tbody></table></div><div class="spectrum-pagination"><div><b>${all.length}</b> antibióticos coincidentes <span>· ${D.relations.length} relaciones registradas</span></div><div class="page-stepper"><button data-act="page:prev" ${page===0?'disabled':''} aria-label="Página anterior">‹</button><span>${total?page+1:0} / ${total}</span><button data-act="page:next" ${page>=total-1?'disabled':''} aria-label="Página siguiente">›</button></div></div>`;}
function precisionCells(a,g){const parts=statusSegments(a,g);return `<div class="precision-strip">${parts.members.map((p,i)=>`<button class="precision-dot st-${parts.values[i]}" data-act="relation:${a.id}:${p.id}" title="${escapeHtml(p.name)} · ${statuses[parts.values[i]].label}">${statuses[parts.values[i]].mark}</button>`).join('')}</div>`}
function selects(){return `<div class="lens-bar"><div class="lens-switch" role="group" aria-label="Tipo de mapa"><button class="${state.lens==='bands'?'on':''}" data-act="lens:bands">${icon('chart-no-axes-gantt',15)} Bandas</button><button class="${state.lens==='precision'?'on':''}" data-act="lens:precision">${icon('grid-3x3',15)} Por especie</button></div><div class="filter-utilities"><button data-act="reset-map">${icon('rotate-ccw',14)} Limpiar</button><button data-act="save-view">${icon('shield-check',15)} Guardar vista</button><button data-act="modal:saved">${icon('layers',15)} Mis vistas</button><button data-act="modal:palette">${icon('palette',16)} Colores</button><button data-act="compact">${icon('list-filter',15)} ${state.prefs.compact?'Ampliar':'Compactar'}</button></div></div><div class="filter-fields">
<label>Microorganismo <select id="sel-pathogen"><option value="all">Todos</option>${D.groups.map(g=>`<optgroup label="${escapeHtml(g.name)}">${groupMembers(g.id).map(p=>`<option value="${p.id}" ${state.pathogen===p.id?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>
<label>Antibiótico <select id="sel-drug"><option value="all">Todos</option>${D.antibiotics.map(a=>`<option value="${a.id}" ${state.drug===a.id?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></label>
<label>Familia <select id="sel-family"><option value="all">Todas</option>${families().map(f=>`<option value="${escapeHtml(f)}" ${state.family===f?'selected':''}>${escapeHtml(f)}</option>`).join('')}</select></label>
<label>Estado <select id="sel-status"><option value="all">Todos</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v.label}</option>`).join('')}</select></label>
</div><div class="filter-detail"><label class="toggle-check"><input id="only-known" type="checkbox" ${state.onlyKnown?'checked':''}> Priorizar ATB con relaciones registradas</label><button data-act="focus:micro" class="quiet-link">${icon('microscope',14)} Elegir micro en la biblioteca</button><span class="filter-active">${[state.group!=='all',state.pathogen!=='all',state.drug!=='all',state.family!=='all',state.status!=='all'].filter(Boolean).length} filtros activos</span></div>`}
function mapPage(){const grp=state.group==='all'?'8 TERRITORIOS VISIBLES':G(state.group)?.name||'Territorio';const filt=[state.group!=='all',state.pathogen!=='all',state.drug!=='all',state.family!=='all',state.status!=='all'].filter(Boolean).length;const active=state.active?.type!=='guide';return `<div class="instrument-title"><div class="instrument-title-left"><span class="instrument-index">01 <span>/</span> MAPA INTERACTIVO</span><h1>El espectro, <em>en perspectiva.</em></h1><p>Una sola superficie para comparar familias, enfocar microorganismos y descubrir el contexto detrás de cada relación.</p></div><div class="instrument-actions"><button data-act="modal:legend">${icon('circle-help',16)} Cómo leerlo</button><button data-act="modal:palette">${icon('palette',16)} Editar colores</button></div></div>
<section class="instrument-workspace" aria-label="Spectrum workbench"><div class="instrument-console"><div class="console-primary"><div class="console-eyebrow">SPECTRUM / WORKSPACE <span class="signal-live"></span></div><div class="console-title"><b>Mapa de actividad</b><span>Compara, filtra y abre un cruce para estudiar.</span></div></div><div class="console-controls"><div class="instrument-lens" role="group" aria-label="Tipo de mapa"><button class="${state.lens==='bands'?'on':''}" data-act="lens:bands">${icon('chart-no-axes-gantt',15)} Espectro</button><button class="${state.lens==='precision'?'on':''}" data-act="lens:precision">${icon('grid-3x3',15)} Por especie</button></div><button class="control-trigger ${state.toolsOpen?'on':''}" data-act="filter-panel" aria-expanded="${!!state.toolsOpen}">${icon('sliders-horizontal',16)} Filtros ${filt?`<span class="filter-count">${filt}</span>`:''}</button></div></div>
<div class="focus-quick"><div class="quick-label"><b>ENFOQUE RÁPIDO</b><span>${escapeHtml(grp)}</span></div><button data-act="reset-map" class="focus-pill ${state.pathogen==='all'?'selected':''}">Panorama</button>${[['p-aeruginosa','Pseudomonas'],['s-aureus-mrsa','MRSA'],['e-coli-blee','E. coli BLEE'],['s-pneumoniae','Neumococo'],['b-fragilis','B. fragilis']].filter(([id])=>P(id)).map(([id,label])=>`<button class="focus-pill ${state.pathogen===id?'selected':''}" data-act="focus-pathogen:${id}">${escapeHtml(label)}</button>`).join('')}<span class="quick-spacer"></span><button class="quiet-tool" data-act="save-view" title="Guardar esta vista">${icon('shield-check',15)} Guardar</button></div>
${state.toolsOpen?`<div class="instrument-filters"><div class="filter-fields"><label>Microorganismo<select id="sel-pathogen"><option value="all">Todos los microorganismos</option>${D.groups.map(g=>`<optgroup label="${escapeHtml(g.name)}">${groupMembers(g.id).map(p=>`<option value="${p.id}" ${state.pathogen===p.id?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><label>Antibiótico<select id="sel-drug"><option value="all">Todos los fármacos</option>${D.antibiotics.map(a=>`<option value="${a.id}" ${state.drug===a.id?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></label><label>Familia<select id="sel-family"><option value="all">Todas las familias</option>${families().map(f=>`<option value="${escapeHtml(f)}" ${state.family===f?'selected':''}>${escapeHtml(f)}</option>`).join('')}</select></label><label>Estado<select id="sel-status"><option value="all">Cualquier estado</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v.label}</option>`).join('')}</select></label></div><label class="filter-toggle"><input type="checkbox" id="only-known" ${state.onlyKnown?'checked':''}> Priorizar antibióticos con relaciones registradas</label><div class="filter-footer"><button data-act="reset-map">${icon('rotate-ccw',14)} Restablecer</button><button data-act="modal:saved">${icon('layers',14)} Vistas guardadas</button><button data-act="compact">${icon('list-filter',14)} ${state.prefs.compact?'Vista normal':'Vista compacta'}</button></div></div>`:''}
${groupSelector()}
<div class="instrument-grid"><div class="instrument-map"><div class="map-ruler"><div><span class="ruler-index">01—A</span><strong>${state.pathogen!=='all'?escapeHtml(P(state.pathogen)?.name||'Microorganismo'):'Panorama por territorios'}</strong></div><span class="ruler-hint">Selecciona cualquier banda para estudiar su detalle <b>↘</b></span></div>${mapTable()}<div class="notation-strip"><span>ACTIVIDAD REGISTRADA</span>${[['active','Habitual'],['conditional','Condicionada'],['none','No útil'],['unknown','Sin evaluar']].map(([id,name])=>`<button data-act="status-help:${id}"><i class="notation-symbol st-${id}">${statuses[id].mark}</i>${name}</button>`).join('')}</div></div></div>
${active?`<div class="context-sheet"><div class="context-cap"><span>${icon('info',16)} NOTA DE CAMPO / DETALLE DEL CRUCE</span><button data-act="close-inspector">Cerrar ${icon('x',13)}</button></div>${inspector()}</div>`:''}</section>
<div class="instrument-bottom"><div class="bottom-message"><span class="bottom-disc">!</span><p><b>El espectro no es una indicación terapéutica.</b> Cada relación requiere especie, fenotipo, susceptibilidad, foco clínico y guía vigente.</p></div><div class="bottom-shortcuts"><button data-act="go:microorganismos">Explorar microorganismos ${icon('arrow-right',14)}</button><button data-act="go:comparar">Comparar antibióticos ${icon('arrow-right',14)}</button></div></div>`;}
function inspector(){const a=state.active;
if(a.type==='guide')return `<section class="inspector" aria-label="Inspector del mapa"><div class="inspector-top"><span class="small-label">INSPECTOR · CONTEXTO</span><span class="live-mark">LIVE FIELD NOTE</span></div><div class="inspector-body inspector-guide"><div class="inspector-graphic"><span>✓</span><span>≈</span><span>×</span><span>·</span></div><div><h3>Selecciona un segmento del mapa.</h3><p>Abre una banda para ver cada microorganismo y su relación registrada con el antibiótico seleccionado.</p></div><div class="inspector-guide-steps"><span>1. Territorio</span><span>2. Especie</span><span>3. Evidencia</span></div></div></section>`;
if(a.type==='group'){
 const drug=A(a.drug),group=G(a.group);if(!drug||!group){state.active={type:'guide'};return inspector()}
 const ms=groupMembers(group.id).filter(p=>state.pathogen==='all'||p.id===state.pathogen);
 return `<section class="inspector" aria-label="Inspector del grupo"><div class="inspector-top"><span class="small-label">INSPECTOR / TERRITORIO</span><button data-act="close-inspector" aria-label="Cerrar inspector">${icon('x',16)}</button></div><div class="inspector-body"><div class="inspector-heading" ${tint(group.id)}><i></i><span>${escapeHtml(group.name)}</span></div><h3>${escapeHtml(drug.name)}</h3><p class="inspector-description">El mismo antibiótico puede mostrar relaciones diferentes dentro de este grupo.</p><div class="species-breakdown">${ms.map(p=>`<button data-act="relation:${drug.id}:${p.id}">${statusChip(status(rel(drug.id,p.id)))}<span>${escapeHtml(p.name)}</span>${icon('chevron-right',14)}</button>`).join('')}</div><div class="inspector-buttons"><button data-act="drug-open:${drug.id}">${icon('pill',15)} Ficha del ATB</button><button data-act="group:${group.id}">${icon('list-filter',15)} Fijar grupo</button></div></div></section>`;
}
if(a.type==='relation'){
 const drug=A(a.drug),p=P(a.pathogen),r=rel(a.drug,a.pathogen);if(!drug||!p){state.active={type:'guide'};return inspector()}
 return `<section class="inspector" aria-label="Inspector del cruce"><div class="inspector-top"><span class="small-label">INSPECTOR / CRUCE INDIVIDUAL</span><button data-act="close-inspector" aria-label="Cerrar inspector">${icon('x',16)}</button></div><div class="inspector-body"><div class="inspector-heading" ${tint(p.groupId)}><i></i><span>${escapeHtml(G(p.groupId)?.name)}</span></div><h3>${escapeHtml(drug.name)} <span>×</span> ${escapeHtml(p.name)}</h3><div class="inspector-state">${statusChip(status(r),true)}</div><p>${escapeHtml(r?.note||statuses.unknown.text)}</p><h4>Qué no debes asumir</h4><p>${escapeHtml(r?.clinical||'Este resultado no establece una indicación clínica. El foco, la susceptibilidad y la epidemiología local pueden cambiar la interpretación.')}</p><h4>Fuentes vinculadas</h4><div class="refs">${refs(r?.sources||r?.referenceKeys)}</div><div class="inspector-buttons"><button data-act="drug-open:${drug.id}">${icon('pill',15)} Ver ATB</button><button data-act="micro-open:${p.id}">${icon('microscope',15)} Ver micro</button></div></div></section>`;
}return '';
}
function mediaOf(p){const m=X.media?.[p.id];return m?`<figure class="photo-panel"><img loading="lazy" src="${escapeHtml(m.src)}" alt="Fotomicrografía de ${escapeHtml(p.name)}"><figcaption>${escapeHtml(m.caption||'Fotomicrografía')} · <a href="${escapeHtml(m.creditUrl||'#')}" target="_blank" rel="noopener noreferrer">${escapeHtml(m.credit||'Fuente')}</a></figcaption></figure>`:`<div class="no-photo"><span>${icon('microscope',38)}</span><b>Identidad microbiológica</b><small>La morfología y el fenotipo se interpretan junto con la clínica y el laboratorio.</small></div>`}
function catalogSidebar(kind){const isMicro=kind==='microorganismos';const items=isMicro?D.pathogens:D.antibiotics;let chosen=isMicro?state.study:state.drug;let filter=state.focus==='faves'?items.filter(x=>state.favorites.includes(x.id)):items;filter=filter.filter(x=>isMicro?state.group==='all'||x.groupId===state.group:state.family==='all'||x.family===state.family);const search=isMicro?state.microSearch||'':state.drugSearch||'';filter=filter.filter(x=>norm(x.name+' '+(x.family||x.morphology||'')).includes(norm(search)));
 const groups=isMicro?D.groups.map(g=>({name:g.name,items:filter.filter(x=>x.groupId===g.id),tone:g.id})):families().map(f=>({name:f,items:filter.filter(x=>x.family===f)}));
return `<aside class="catalog-sidebar"><div class="catalog-side-head"><div class="section-serial">CATÁLOGO <span>${items.length} ENTRADAS</span></div><div class="catalog-search">${icon('search',16)}<input id="catalog-query" data-collection="${kind}" type="search" placeholder="Buscar por nombre…" value="${escapeHtml(search)}"></div><div class="catalog-tools"><button data-act="all-catalog" class="${state.focus!=='faves'?'on':''}">Todos</button><button data-act="faves" class="${state.focus==='faves'?'on':''}">${icon('shield-check',14)} Guardados</button></div></div><div class="catalog-list">${groups.filter(x=>x.items.length).map(g=>`<div class="catalog-group"><h3 ${g.tone?tint(g.tone):''}><i></i>${escapeHtml(g.name)} <small>${g.items.length}</small></h3>${g.items.map(x=>`<button class="catalog-choice ${chosen===x.id?'on':''}" data-act="${isMicro?'micro-open':'drug-open'}:${x.id}"><span><b>${escapeHtml(short(x.name))}</b><small>${escapeHtml(isMicro?x.morphology||'':x.subgroup||'')}</small></span>${icon('chevron-right',14)}</button>`).join('')}</div>`).join('')||'<p class="catalog-empty">Sin resultados. Prueba limpiar la búsqueda.</p>'}</div></aside>`}
function bookmarkBtn(id){return `<button class="bookmark ${state.favorites.includes(id)?'bookmarked':''}" data-act="bookmark:${id}">${icon('shield-check',16)} ${state.favorites.includes(id)?'Guardado':'Guardar ficha'}</button>`}
function listRels(grouped,isMicro,id){const list=relatives(isMicro?microRel:drugRel,id);
return `<section class="content-section"><div class="section-heading"><div><span class="small-label">ESPECTRO REGISTRADO</span><h3>${isMicro?'Antibióticos relacionados':'Patógenos relacionados'}</h3></div><small>${list.length} cruces registrados</small></div><div class="clinical-relations">${['active','conditional','none'].map(k=>`<div class="relation-column"><div class="column-title">${statusChip(k)}</div>${list.filter(r=>r.status===k).map(r=>{const other=isMicro?A(r.antibiotic):P(r.pathogen);return `<button data-act="relation:${r.antibiotic}:${r.pathogen}"><b>${escapeHtml(short(other?.name||'ID desconocido'))}</b>${icon('arrow-up-right',14)}</button>`}).join('')||'<span class="muted">Sin cruces registrados</span>'}</div>`).join('')}</div><p class="caution">La cobertura teórica no sustituye antibiograma, farmacocinética, diagnóstico ni guías. Cruces del piloto pendientes de revisión individual.</p></section>`}
function microPage(){const p=P(state.study)||D.pathogens[0];return `${pageHeading('02 / ORGANISM INDEX','Conoce al <em>microorganismo.</em>','Microbiología que conecta la identidad con sus enfermedades, pistas diagnósticas y opciones que requieren evaluación.','<span class="edition-tag">MICRO ATLAS · 79 ENTRADAS</span>')}<div class="catalog-layout">${catalogSidebar('microorganismos')}<section class="catalog-main"><div class="species-cover" ${tint(p.groupId)}><div class="species-number">MICRO / ${num(D.pathogens.indexOf(p)+1)}</div><div><span class="species-label"><i></i> ${escapeHtml(G(p.groupId)?.name||'Grupo')}</span><h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.identity||'Ficha de identidad en desarrollo.')}</p><div class="species-tags">${pill(p.morphology||'Morfología pendiente')}${pill(p.domain||'')}${pill((p.aliases||[]).join(' · ')||'Sin alias')}</div></div><div class="species-actions">${bookmarkBtn(p.id)}<button data-act="micro-map:${p.id}">${icon('table-2',16)} Ver en mapa</button></div></div><div class="detail-grid"><div class="detail-primary"><section class="content-section"><div class="section-heading"><div><span class="small-label">01 / IDENTIDAD CLÍNICA</span><h3>Cómo reconocerlo y cuándo sospecharlo</h3></div></div><p class="feature-lead">${escapeHtml(p.clinical||'El síndrome y el contexto epidemiológico orientan la sospecha.')}</p><div class="split-facts"><div><b>${icon('microscope',17)} Morfología</b><p>${escapeHtml(p.morphology||'Por completar')}</p></div><div><b>${icon('lightbulb',17)} Clave para recordar</b><p>${escapeHtml(p.pearl||'Interpretar según especie y fenotipo')}</p></div></div></section>${listRels([],true,p.id)}<section class="content-section"><div class="section-heading"><h3>Síndromes relacionados</h3></div><div class="syndrome-links">${(p.syndromeIds||[]).map(id=>S(id)?`<button data-act="syndrome:${id}">${icon('stethoscope',17)} ${escapeHtml(S(id).name)} ${icon('arrow-right',14)}</button>`:'').join('')||'<p class="muted">No hay vínculos de síndrome registrados para esta ficha.</p>'}</div></section></div><aside class="detail-aside">${mediaOf(p)}<div class="teaching-note"><span class="small-label">CLINICAL NOTE</span><h3>La especie no equivale al fenotipo.</h3><p>MRSA, BLEE o DTR requieren criterios microbiológicos. Una microfotografía no establece susceptibilidad.</p></div><div class="reference-box"><b>Fuentes de la ficha</b><div class="refs">${refs(p.referenceKeys)}</div></div></aside></div></section></div>`}
function drugPage(){const a=A(state.drug)||D.antibiotics[0];return `${pageHeading('03 / DRUG INDEX','Una biblioteca de <em>antibióticos.</em>','Familias y subgrupos farmacológicos con mecanismos, contexto y relaciones microbiológicas explícitas.','<span class="edition-tag">DRUG ATLAS · 111 AGENTES</span>')}<div class="catalog-layout">${catalogSidebar('antibioticos')}<section class="catalog-main"><div class="drug-cover"><div class="species-number">ANTIBIÓTICO / ${num(D.antibiotics.indexOf(a)+1)}</div><div class="drug-art">${icon('pill',47)}<span>Rx</span></div><div><span class="drug-family">${escapeHtml(a.family)} / ${escapeHtml(a.subgroup||'')}</span><h2>${escapeHtml(a.name)}</h2><p>${escapeHtml(a.pearl||'La utilidad depende de susceptibilidad, infección y características del huésped.')}</p></div><div class="species-actions">${bookmarkBtn(a.id)}<button data-act="drug-map:${a.id}">${icon('table-2',16)} Ubicar en mapa</button><button data-act="add-compare:${a.id}">${icon('columns-3',16)} Comparar</button></div></div><div class="detail-grid"><div class="detail-primary"><section class="content-section"><div class="section-heading"><div><span class="small-label">01 / MODO DE ACCIÓN</span><h3>Qué hace y dónde puede importar</h3></div></div><p class="feature-lead">${escapeHtml(a.mechanism||'Mecanismo en desarrollo.')}</p><div class="split-facts"><div><b>${icon('circuit-board',17)} Aplicación conceptual</b><p>${escapeHtml(a.context||'Consultar indicaciones según guía y sensibilidad.')}</p></div><div><b>${icon('shield-alert',17)} Limitaciones</b><p>${escapeHtml(a.limitations||'Verificar contra especie, foco y farmacocinética.')}</p></div></div></section>${listRels([],false,a.id)}</div><aside class="detail-aside"><div class="spectrum-mini"><span class="small-label">MAPA / PERFIL VINCULADO</span><h3>¿Dónde hay datos?</h3><p>Estos bloques indican cruces registrados por grupo, no porcentaje de sensibilidad.</p>${D.groups.map(g=>{const found=relatives(drugRel,a.id).filter(r=>P(r.pathogen)?.groupId===g.id);return `<button ${tint(g.id)} data-act="group-map:${g.id}:${a.id}"><i></i><span>${escapeHtml(g.name)}</span><b>${found.length}</b></button>`}).join('')}</div><div class="reference-box"><b>Fuentes de la ficha</b><div class="refs">${refs(a.referenceKeys)}</div></div></aside></div></section></div>`}
function clinicalPage(){const current=S(state.syndrome)||D.syndromes[0];const syms=D.syndromes.filter(x=>state.clinicalSite==='all'||!state.clinicalSite||x.site===state.clinicalSite);return `${pageHeading('04 / CLINICAL PATHWAYS','Partir del <em>síndrome.</em>','Un recorrido de reconocimiento, patógenos posibles y contraste de fuentes, sin prescripción automática.')}<div class="clinical-workspace"><div class="clinical-index"><div class="section-serial">01 <span>EXPLORAR POR SITIO</span></div><select id="clinical-site"><option value="all">Todas las localizaciones</option>${[...new Set(D.syndromes.map(x=>x.site))].map(site=>`<option value="${escapeHtml(site)}" ${state.clinicalSite===site?'selected':''}>${escapeHtml(site)}</option>`).join('')}</select><div class="clinical-items">${syms.map((s,i)=>`<button class="${current.id===s.id?'selected':''}" data-act="syndrome:${s.id}"><small>${num(i+1)}</small><b>${escapeHtml(s.name)}</b><span>${escapeHtml(s.site)}</span>${icon('chevron-right',15)}</button>`).join('')}</div></div><section class="clinical-article"><span class="eyebrow"><i></i>CASO / ${escapeHtml(current.site)}</span><h2>${escapeHtml(current.name)}</h2><p class="feature-lead">${escapeHtml(current.summary||'')}</p><div class="pathway"><div><span>01</span><b>Reconocer</b><small>Foco, gravedad, evolución</small></div><div><span>02</span><b>Considerar</b><small>Agentes y contexto</small></div><div><span>03</span><b>Verificar</b><small>Guías y susceptibilidad</small></div></div><div class="clinical-columns"><section><h3>Claves de contexto</h3><ul>${(current.clues||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></section><section><h3>Microorganismos a considerar</h3><div class="clinical-agents">${(current.pathogenIds||[]).map(id=>P(id)?`<button ${tint(P(id).groupId)} data-act="micro-open:${id}"><i></i><span>${escapeHtml(P(id).name)}</span>${icon('arrow-up-right',13)}</button>`:'').join('')}</div></section></div><div class="reference-box"><b>Guías vinculadas</b><div class="refs">${refs(current.referenceKeys)}</div></div><p class="caution">No se recomienda un tratamiento empírico automáticamente: requiere evaluación de huésped, gravedad, epidemiología y guía vigente.</p></section></div>`}
function comparePage(){const selected=state.compare.map(A).filter(Boolean);const microbes=D.pathogens.filter(p=>selected.some(a=>rel(a.id,p.id))&&(state.group==='all'||p.groupId===state.group));return `${pageHeading('05 / HEAD TO HEAD','Comparar sin <em>adivinar.</em>','Selecciona hasta cuatro agentes y observa las mismas especies. La ausencia de un dato no debe compararse como resistencia.')}
<div class="compare-toolbar"><div><span class="small-label">SELECCIÓN ACTUAL</span><div class="compare-pills">${selected.map(a=>`<button data-act="remove-compare:${a.id}">${escapeHtml(a.name)} <b>×</b></button>`).join('')||'<span>Agrega al menos un fármaco.</span>'}</div></div><label>Agregar ATB <select id="add-compare"><option value="">Selecciona un agente…</option>${D.antibiotics.filter(a=>!state.compare.includes(a.id)).map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}</select></label><label>Grupo microbiano <select id="compare-group"><option value="all">Todos los grupos</option>${D.groups.map(g=>`<option value="${g.id}" ${state.group===g.id?'selected':''}>${escapeHtml(g.name)}</option>`).join('')}</select></label></div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>MICROORGANISMO</th>${selected.map(a=>`<th><b>${escapeHtml(a.name)}</b><small>${escapeHtml(a.family)}</small></th>`).join('')}</tr></thead><tbody>${microbes.map(p=>`<tr><th ${tint(p.groupId)}><button data-act="micro-open:${p.id}"><i></i>${escapeHtml(p.name)}</button><small>${escapeHtml(G(p.groupId)?.name||'')}</small></th>${selected.map(a=>`<td><button data-act="relation:${a.id}:${p.id}">${statusChip(status(rel(a.id,p.id)))}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="under-table">${legend(true)}</div>`}
const quiz=[
 {q:'Si el mapa muestra «· No evaluado» para un cruce, ¿qué significa?',options:['Resistencia comprobada','Sin datos registrados en el atlas','Antibiótico contraindicado'],answer:1,why:'La ausencia de una relación cargada no establece resistencia, ni actividad, ni una recomendación clínica.'},
 {q:'Un aislamiento de S. aureus es MRSA. ¿Qué afirmación es correcta?',options:['La morfología demuestra MRSA','Se requiere determinar el fenotipo de resistencia','Todos los betalactámicos son equivalentes'],answer:1,why:'MSSA y MRSA tienen morfología equivalente; la susceptibilidad se determina mediante pruebas apropiadas.'},
 {q:'Un microorganismo tiene actividad microbiológica descrita frente a un fármaco. ¿Qué sigue?',options:['Prescribir sin más datos','Revisar foco, antibiograma, huésped y guía','Asumir que es primera línea'],answer:1,why:'Actividad no implica necesariamente tratamiento de elección. Importan PK/PD, foco y contexto.'}
];
function labPage(){const p=P(state.study)||D.pathogens[0];const selected=state.compare.map(A).filter(Boolean);const q=quiz[state.quizStep%quiz.length];return `${pageHeading('06 / HANDS-ON LAB','Un laboratorio para <em>aprender haciendo.</em>','Prueba hipótesis, modifica los fármacos y descubre qué datos necesitas antes de interpretar la actividad.')}
<div class="lab-top"><button class="${state.course===0?'selected':''}" data-act="course:0">${icon('flask-conical',18)} Mesa de espectro</button><button class="${state.course===1?'selected':''}" data-act="course:1">${icon('graduation-cap',18)} Reto explicado</button></div>${state.course===0?`<div class="lab-grid"><section class="lab-selector"><span class="small-label">ELEGIR UN MICROORGANISMO</span><h2>¿Qué queremos estudiar?</h2><select id="lab-micro">${D.pathogens.map(m=>`<option value="${m.id}" ${m.id===p.id?'selected':''}>${escapeHtml(m.name)}</option>`).join('')}</select><div class="lab-profile" ${tint(p.groupId)}><i></i><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.morphology||'')}</small><p>${escapeHtml(p.pearl||'')}</p></div><p>Selecciona hasta 4 fármacos y compara sus relaciones registradas.</p><label>Añadir a la mesa<select id="lab-add"><option value="">Seleccionar antibiótico</option>${D.antibiotics.filter(a=>!state.compare.includes(a.id)).map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}</select></label></section><section class="lab-desk"><span class="small-label">MESA DE ESPECTRO · HASTA 4 AGENTES</span><h2>Comparación frente a <em>${escapeHtml(p.name)}</em></h2><div class="lab-drugs">${selected.map((a,i)=>`<div class="lab-drug" draggable="true" data-drag="${a.id}"><div class="drag-id">${icon('layers',17)} ${num(i+1)} <button data-act="remove-compare:${a.id}">×</button></div><h3>${escapeHtml(a.name)}</h3><small>${escapeHtml(a.family)}</small>${statusChip(status(rel(a.id,p.id)),true)}<button class="review-link" data-act="relation:${a.id}:${p.id}">Explicar este cruce ${icon('arrow-right',14)}</button></div>`).join('')||'<div class="lab-empty">Agrega un antibiótico a la mesa de trabajo.</div>'}</div><p class="caution">Los cruces piloto no son una recomendación terapéutica. Arrastra las tarjetas para ordenarlas o selecciónalas directamente.</p></section></div>`:`<section class="quiz-shell"><span class="small-label">PREGUNTA ${state.quizStep+1} / ${quiz.length}</span><div class="quiz-progress"><span style="width:${((state.quizStep+1)/quiz.length)*100}%"></span></div><h2>${escapeHtml(q.q)}</h2><div class="quiz-choices">${q.options.map((option,i)=>`<button class="${state.quizAnswer!==null?(i===q.answer?'correct':i===state.quizAnswer?'wrong':'dim'):''}" data-act="answer:${i}" ${state.quizAnswer!==null?'disabled':''}><b>${'ABC'[i]}</b>${escapeHtml(option)}</button>`).join('')}</div>${state.quizAnswer!==null?`<div class="quiz-answer"><h3>${state.quizAnswer===q.answer?'Bien razonado':'Revisa el concepto'}</h3><p>${escapeHtml(q.why)}</p><button data-act="next-question">${state.quizStep===quiz.length-1?'Reiniciar reto':'Siguiente pregunta'} ${icon('arrow-right',14)}</button></div>`:''}</section>`}`}
function learnPage(){const lessons=[...(X.topics||[]).map(x=>({title:x.name,subtitle:x.hint,body:x.explain,why:x.why,link:x.link})),...(D.lessons||[]).map(x=>({title:x.title,subtitle:x.category,body:x.summary||x.body||x.text||'',why:x.why||'',link:''}))];const l=lessons[state.lesson]||lessons[0];return `${pageHeading('07 / STUDY NOTES','Microbiología que <em>se comprende.</em>','Lecciones breves y notas clínicas, para ir de la identidad al mecanismo y de ahí al uso informado.')}
<div class="learn-layout"><aside class="learn-menu"><span class="small-label">LECCIONES / ${lessons.length}</span>${lessons.map((x,i)=>`<button class="${state.lesson===i?'selected':''}" data-act="lesson:${i}"><small>${num(i+1)}</small><span>${escapeHtml(x.title)}</span>${icon('chevron-right',14)}</button>`).join('')}</aside><article class="learn-body"><span class="small-label">STUDY NOTE / ${num(state.lesson+1)}</span><h2>${escapeHtml(l.title)}</h2><div class="teaching-note"><b>Idea para retener</b><p>${escapeHtml(l.subtitle||'')}</p></div><h3>Comprender el mecanismo</h3><p>${escapeHtml(l.body||'Nota educativa en revisión.')}</p><h3>¿Por qué importa?</h3><p>${escapeHtml(l.why||'Relaciona mecanismo, foco, susceptibilidad y evidencia.')}</p>${l.link?`<a href="${escapeHtml(l.link)}" target="_blank" rel="noopener noreferrer" class="outlink">Abrir referencia externa ${icon('arrow-up-right',15)}</a>`:''}</article></div>`}
function sourcesPage(){return `${pageHeading('08 / REFERENCE INDEX','La evidencia <em>detrás del atlas.</em>','Fuentes y guías enlazadas. El inventario bibliográfico no implica que todas las relaciones hayan sido revisadas clínicamente.')}
<div class="sources-gallery">${Object.entries(D.guides).map(([id,s],i)=>`<a href="${escapeHtml(s.url||'#')}" target="_blank" rel="noopener noreferrer"><span class="src-n">${num(i+1)}</span><span class="src-tag">${escapeHtml(s.category||'REFERENCIA')} · ${escapeHtml(s.year||'')}</span><h2>${escapeHtml(s.title||id)}</h2><p>${escapeHtml(s.topic||s.takeaway||'Consulta el recurso para ver el contexto completo.')}</p><span class="src-bottom">Consultar recurso ${icon('arrow-up-right',16)}</span></a>`).join('')}</div>`}
function modalMarkup(){if(state.modal==='search'){
 const q=norm(state.globalQuery);const options=[...D.pathogens.map(x=>({id:x.id,type:'micro-open',name:x.name,label:G(x.groupId)?.name||'Microorganismo',ico:'microscope'})),...D.antibiotics.map(x=>({id:x.id,type:'drug-open',name:x.name,label:x.family,ico:'pill'})),...D.syndromes.map(x=>({id:x.id,type:'syndrome',name:x.name,label:x.site,ico:'stethoscope'}))].filter(x=>!q||norm(x.name+' '+x.label).includes(q)).slice(0,25);
 return `<div class="modal-back" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-title"><span class="small-label">COMMAND SEARCH</span><button data-act="close-modal">${icon('x',19)}</button></div><div class="command-box">${icon('search',23)}<input id="global-search-input" autofocus placeholder="Cefepima, MRSA, neumonía…" value="${escapeHtml(state.globalQuery)}"></div><div class="command-results">${options.map(x=>`<button data-act="${x.type}:${x.id}">${icon(x.ico,18)}<span><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.label)}</small></span>${icon('arrow-up-right',15)}</button>`).join('')||'<p>Sin resultados</p>'}</div></div></div>`;
}
if(state.modal==='saved')return `<div class="modal-back" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-title"><div><span class="small-label">BOOKMARKS / VISTAS\</span><h2>Tu estudio, donde lo dejaste.</h2><p>Estas vistas permanecen guardadas en este navegador.</p></div><button data-act="close-modal">${icon('x',19)}</button></div><div class="saved-views">${state.saved.map((v,i)=>`<button data-act="restore-view:${i}"><b>Vista ${num(i+1)}</b><span>${escapeHtml(v.group==='all'?'Todos los grupos':G(v.group)?.name||v.group)} · ${escapeHtml(v.drug==='all'?'Todos los ATB':A(v.drug)?.name||v.drug)}</span>${icon('arrow-right',15)}</button>`).join('')||'<p class="muted">Aún no has guardado vistas. Aplica filtros y utiliza «Guardar vista».</p>'}</div></div></div>`;
if(state.modal==='palette')return `<div class="modal-back" data-act="close-modal"><div class="modal palette-modal" role="dialog" aria-modal="true"><div class="modal-title"><div><span class="small-label">CHROMATIC STUDIO</span><h2>El atlas, a tu manera.</h2><p>Personaliza la identidad de cada grupo. La actividad siempre usa símbolos independientes.</p></div><button data-act="close-modal">${icon('x',19)}</button></div><div class="theme-grid">${Object.entries(themes).map(([id,cols])=>`<button class="theme-option ${state.theme===id?'selected':''}" data-act="theme:${id}"><span>${cols.slice(0,7).map(c=>`<i style="background:${c}"></i>`).join('')}</span><b>${catLabels[id]}</b></button>`).join('')}</div><h3>Colores por territorio</h3><div class="color-editor">${D.groups.map(g=>`<label ${tint(g.id)}><i></i><span>${escapeHtml(g.name)}</span><input type="color" data-color="${g.id}" value="${escapeHtml(color(g.id))}" aria-label="Color de ${escapeHtml(g.name)}"></label>`).join('')}</div><div class="modal-footer"><button data-act="reset-palette">Restablecer</button><button data-act="copy-palette">${icon('copy',15)} Copiar configuración</button></div></div></div>`;
if(state.modal.startsWith('status:')){const k=state.modal.split(':')[1],v=statuses[k];return `<div class="modal-back" data-act="close-modal"><div class="modal short-modal" role="dialog" aria-modal="true"><div class="modal-title"><span class="small-label">CÓMO LEER LA COBERTURA</span><button data-act="close-modal">${icon('x',19)}</button></div><div class="giant-symbol st-${k}">${v.mark}</div><h2>${v.label}</h2><p>${v.text}</p><div class="caution">Estos símbolos representan el contenido disponible en el atlas. No son porcentajes de sensibilidad.</div></div></div>`}
if(state.modal==='legend')return `<div class="modal-back" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true"><div class="modal-title"><div><span class="small-label">VISUAL GRAMMAR</span><h2>Lee el mapa en 20 segundos.</h2></div><button data-act="close-modal">${icon('x',19)}</button></div><div class="legend-lesson"><div><span class="large-number">01</span><h3>El color es identidad.</h3><p>Los colores del encabezado señalan territorios microbiológicos. No significan sensibilidad.</p><div class="color-mini">${D.groups.slice(0,9).map(g=>`<i style="background:${color(g.id)}" title="${escapeHtml(g.name)}"></i>`).join('')}</div></div><div><span class="large-number">02</span><h3>El símbolo es actividad.</h3><p>Los símbolos expresan relaciones registradas; un espacio sin dato no demuestra resistencia.</p>${legend()}</div><div><span class="large-number">03</span><h3>El clic abre la fuente.</h3><p>Abre una banda, elige especie y consulta nota clínica y referencias.</p></div></div></div></div>`;
return '';
}
function toast(s){const previous=document.querySelector('.toast');if(previous)previous.remove();const box=document.createElement('div');box.className='toast';box.textContent=s;box.setAttribute('role','status');document.body.appendChild(box);setTimeout(()=>box.remove(),2400)}
function action(name){const [cmd,...params]=name.split(':'),arg=params.join(':');
 if(cmd==='go')return navigate(arg);
 if(cmd==='toggle-nav'){state.navOpen=!state.navOpen;return render()}
 if(cmd==='modal'){state.modal=arg;state.globalQuery='';render();if(arg==='search')document.querySelector('#global-search-input')?.focus();return}
 if(cmd==='close-modal'){state.modal=null;return render()}
 if(cmd==='status-help'){state.modal='status:'+arg;return render()}
 if(cmd==='filter-panel'){state.toolsOpen=!state.toolsOpen;return render()}
 if(cmd==='focus-pathogen'){state.pathogen=arg;state.group=P(arg)?.groupId||'all';state.page=0;return render()}
 if(cmd==='group'){state.group=arg;state.page=0;state.pathogen='all';return render()}
 if(cmd==='lens'){state.lens=arg;return render()}
 if(cmd==='page'){state.page=Math.max(0,state.page+(arg==='next'?1:-1));return render()}
 if(cmd==='reset-map'){Object.assign(state,{group:'all',pathogen:'all',family:'all',drug:'all',status:'all',query:'',page:0,onlyKnown:true,active:{type:'guide'}});return render()}
 if(cmd==='inspect'){state.active={type:'group',drug:params[0],group:params[1]};return render()}
 if(cmd==='relation'){state.active={type:'relation',drug:params[0],pathogen:params[1]};state.modal=null;if(state.route!=='mapa'){state.drug=params[0];state.pathogen=params[1];state.group=P(params[1])?.groupId||'all';navigate('mapa')}return render()}
 if(cmd==='close-inspector'){state.active={type:'guide'};return render()}
 if(cmd==='drug-open'){state.drug=arg;state.focus='none';return navigate('antibioticos')}
 if(cmd==='micro-open'){state.study=arg;state.focus='none';return navigate('microorganismos')}
 if(cmd==='drug-map'){state.drug=arg;state.page=0;state.group='all';return navigate('mapa')}
 if(cmd==='micro-map'){state.pathogen=arg;state.group=P(arg)?.groupId||'all';state.page=0;return navigate('mapa')}
 if(cmd==='group-map'){state.group=params[0];state.drug=params[1];state.page=0;return navigate('mapa')}
 if(cmd==='focus'){return navigate(arg==='micro'?'microorganismos':'antibioticos')}
 if(cmd==='syndrome'){state.syndrome=arg;return navigate('clinica')}
 if(cmd==='all-catalog'){state.focus='none';return render()}
 if(cmd==='faves'){state.focus='faves';return render()}
 if(cmd==='bookmark'){state.favorites=state.favorites.includes(arg)?state.favorites.filter(x=>x!==arg):[...state.favorites,arg];persist();return render()}
 if(cmd==='theme'){state.theme=arg;state.colors=Object.fromEntries(D.groups.map((g,i)=>[g.id,themes[arg][i%12]]));persist();return render()}
 if(cmd==='reset-palette'){state.theme='pigment';state.colors=Object.fromEntries(D.groups.map((g,i)=>[g.id,themes.pigment[i%12]]));persist();return render()}
 if(cmd==='copy-palette'){navigator.clipboard?.writeText(JSON.stringify({theme:state.theme,groups:state.colors},null,2)).then(()=>toast('Paleta copiada')).catch(()=>toast('No fue posible copiar'));return}
 if(cmd==='share'){const url=location.href;navigator.clipboard?.writeText(url).then(()=>toast('Enlace copiado')).catch(()=>toast('Copia la dirección del navegador'));return}
 if(cmd==='compact'){state.prefs.compact=!state.prefs.compact;persist();return render()}
 if(cmd==='restore-view'){const v=state.saved[Number(arg)];if(v){Object.assign(state,{...v,page:0,active:{type:'guide'}});state.modal=null;return navigate('mapa')}return}
 if(cmd==='add-compare'){if(!state.compare.includes(arg)){if(state.compare.length>=4)return toast('Máximo 4 antibióticos');state.compare.push(arg)}return navigate('comparar')}
 if(cmd==='save-view'){const snapshot={group:state.group,pathogen:state.pathogen,family:state.family,drug:state.drug,status:state.status,lens:state.lens};state.saved=[snapshot,...state.saved.filter(x=>JSON.stringify(x)!==JSON.stringify(snapshot))].slice(0,10);persist();return toast('Vista guardada en este navegador')}
 if(cmd==='remove-compare'){state.compare=state.compare.filter(x=>x!==arg);return render()}
 if(cmd==='course'){state.course=Number(arg);return render()}
 if(cmd==='answer'){state.quizAnswer=Number(arg);return render()}
 if(cmd==='next-question'){state.quizStep=(state.quizStep+1)%quiz.length;state.quizAnswer=null;return render()}
 if(cmd==='lesson'){state.lesson=Number(arg);return render()}
}
function render(){if(!D)return;const route=state.route;const body=route==='mapa'?mapPage():route==='microorganismos'?microPage():route==='antibioticos'?drugPage():route==='clinica'?clinicalPage():route==='comparar'?comparePage():route==='laboratorio'?labPage():route==='aprender'?learnPage():sourcesPage();app.innerHTML=shell(body)}
app.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;
 if(el.classList.contains('modal-back')&&e.target!==el)return;
 action(el.dataset.act)
});
app.addEventListener('change',e=>{const el=e.target,k=el.id,value=el.value;
 const direct={'sel-pathogen':'pathogen','sel-drug':'drug','sel-family':'family','sel-status':'status','clinical-site':'clinicalSite','compare-group':'group','lab-micro':'study'};
 if(direct[k]){state[direct[k]]=value;state.page=0;if(k==='sel-pathogen')state.group=value==='all'?'all':P(value)?.groupId||'all';return render()}
 if(k==='only-known'){state.onlyKnown=el.checked;state.page=0;return render()}
 if(k==='add-compare'||k==='lab-add'){if(value&&!state.compare.includes(value)){if(state.compare.length===4)return toast('Máximo 4 antibióticos');state.compare.push(value)}return render()}
 if(el.dataset.color){state.colors=state.colors||{};state.colors[el.dataset.color]=value;persist();return render()}
});
app.addEventListener('input',e=>{const el=e.target;
 if(el.id==='global-search-input'){state.globalQuery=el.value;const pos=el.selectionStart;const modal=state.modal;render();state.modal=modal;const fresh=document.getElementById('global-search-input');fresh?.focus();try{fresh?.setSelectionRange(pos,pos)}catch{}return}
 if(el.id==='catalog-query'){const prop=el.dataset.collection==='microorganismos'?'microSearch':'drugSearch';state[prop]=el.value;const pos=el.selectionStart;render();const fresh=document.getElementById('catalog-query');fresh?.focus();try{fresh?.setSelectionRange(pos,pos)}catch{}return}
 if(el.dataset.color){state.colors=state.colors||{};state.colors[el.dataset.color]=el.value;persist();el.closest('label')?.style.setProperty('--tax',el.value)}
});
app.addEventListener('dragstart',e=>{const item=e.target.closest('[data-drag]');if(item){e.dataTransfer.setData('text/plain',item.dataset.drag);e.dataTransfer.effectAllowed='move'}});
app.addEventListener('dragover',e=>{if(e.target.closest('.lab-drugs'))e.preventDefault()});
app.addEventListener('drop',e=>{const tile=e.target.closest('[data-drag]');const id=e.dataTransfer?.getData('text/plain');if(!id||!state.compare.includes(id)||!tile||tile.dataset.drag===id)return;e.preventDefault();const from=state.compare.indexOf(id),to=state.compare.indexOf(tile.dataset.drag);if(from<0||to<0)return;state.compare.splice(from,1);state.compare.splice(to,0,id);render()});
window.addEventListener('hashchange',()=>{state.modal=null;const p=location.hash.match(/^#\/(mapa|microorganismos|antibioticos|clinica|comparar|laboratorio|aprender|fuentes)/);state.route=p?.[1]||'mapa';state.active={type:'guide'};render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal){state.modal=null;render()}else if(state.active?.type!=='guide'){state.active={type:'guide'};render()}}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.modal='search';state.globalQuery='';render();document.getElementById('global-search-input')?.focus()}});
async function boot(){try{const [r1,r2]=await Promise.all([fetch('./data/atlas.json'),fetch('./data/insights.json')]);if(!r1.ok||!r2.ok)throw Error('No se pudieron cargar los datos del atlas');D=await r1.json();X=await r2.json();
 if(!D.groups||!D.antibiotics||!D.pathogens||!D.relations)throw Error('Corpus no válido');
 for(const r of D.relations){rmap.set(r.antibiotic+'|'+r.pathogen,r);drugRel.set(r.antibiotic,[...(drugRel.get(r.antibiotic)||[]),r]);microRel.set(r.pathogen,[...(microRel.get(r.pathogen)||[]),r])}
 if(!state.colors||typeof state.colors!=='object')state.colors={};for(const [i,g]of D.groups.entries()){if(!/^#[\da-f]{6}$/i.test(state.colors[g.id]||''))state.colors[g.id]=themes[state.theme][i%12]}
 const match=location.hash.match(/^#\/(mapa|microorganismos|antibioticos|clinica|comparar|laboratorio|aprender|fuentes)/);state.route=match?.[1]||'mapa';if(!location.hash)history.replaceState(null,'',location.pathname+location.search+'#/mapa');render();
 }catch(err){console.error(err);app.innerHTML=`<div class="boot error"><h2>No se pudo cargar ATB Atlas</h2><p>${escapeHtml(err.message)}</p></div>`}}
boot();